const crypto = require('crypto');
const sign = (secret, timestamp, body) =>
  'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
const signedRequest = (path, bodyObject) => {
  const secret = $env.LENDLOOP_INBOUND_SECRET;
  if (!secret) throw new Error('LENDLOOP_INBOUND_SECRET is not set');
  const base = String($env.LENDLOOP_CONVEX_SITE_URL || 'http://convex-backend:3211').replace(/\/+$/, '');
  const timestamp = String(Math.floor(Date.now() / 1000));
  const body = JSON.stringify(bodyObject);
  return {
    url: base + path,
    body,
    headers: {
      'Content-Type': 'application/json',
      'X-LendLoop-Timestamp': timestamp,
      'X-LendLoop-Signature': sign(secret, timestamp, body),
      'X-LendLoop-Event-Id': bodyObject.idempotencyKey || ''
    }
  };
};
const asOf = new Date().toLocaleDateString('en-CA', { timeZone: $env.GENERIC_TIMEZONE || 'UTC' });
return [{ json: { asOf, ...signedRequest('/n8n/upcoming-pickups', { asOf }) } }];

const res = $input.first().json;
const asOf = res.asOf || $('Sign upcoming-pickups request').last().json.asOf;
return (res.loans || []).map((loan) => ({ json: { ...loan, asOf } }));

const crypto = require('crypto');
const sign = (secret, timestamp, body) =>
  'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
const signedRequest = (path, bodyObject) => {
  const secret = $env.LENDLOOP_INBOUND_SECRET;
  if (!secret) throw new Error('LENDLOOP_INBOUND_SECRET is not set');
  const base = String($env.LENDLOOP_CONVEX_SITE_URL || 'http://convex-backend:3211').replace(/\/+$/, '');
  const timestamp = String(Math.floor(Date.now() / 1000));
  const body = JSON.stringify(bodyObject);
  return {
    url: base + path,
    body,
    headers: {
      'Content-Type': 'application/json',
      'X-LendLoop-Timestamp': timestamp,
      'X-LendLoop-Signature': sign(secret, timestamp, body),
      'X-LendLoop-Event-Id': bodyObject.idempotencyKey || ''
    }
  };
};
const loan = $('Loop Over Items').first().json;
const idempotencyKey = 'pickup-reminder:' + loan.loanId + ':' + loan.asOf;
return { json: signedRequest('/n8n/pickup-reminder-sent', { idempotencyKey, loanId: loan.loanId, asOf: loan.asOf }) };

const loan = $('Loop Over Items').first().json;
const err = $json.error;
const error = String((typeof err === 'string' ? err : err && err.message) || 'send or write-back failed').slice(0, 200);
return { json: { ok: false, loanId: loan.loanId, error } };

const MAX_PAGES = 10;
const results = $input.all().map((i) => i.json);
const failed = results.filter((r) => r.ok === false);
const store = $getWorkflowStaticData('node');
if ($runIndex === 0 || !Array.isArray(store.failures)) store.failures = [];
store.failures.push(...failed.map((f) => ({ loanId: f.loanId, error: f.error })));
const hasMore = $('Fetch upcoming pickups').last().json.hasMore === true;
// only page on while something was actually processed, otherwise the same failing loans fill every page
const canContinue = hasMore && results.length > failed.length && $runIndex < MAX_PAGES - 1;
return [{ json: { page: $runIndex + 1, hasMore, canContinue, failedTotal: store.failures.length, failures: store.failures.slice(0, 20) } }];

const s = $input.first().json;
if (s.failedTotal > 0 || s.hasMore) {
  const list = s.failures.map((f) => f.loanId + ': ' + f.error).join('; ');
  throw new Error('pickup reminders incomplete: ' + s.failedTotal + ' failed' + (s.hasMore ? ', more items remain' : '') + (list ? ' (' + list + ')' : ''));
}
return [{ json: s }];
